action.mutation:
mutation UpdateDataFlowSchedule($payload: [DataFlowScheduleUpdatePayloadInput!]!) {
  mutation: updateDataFlowSchedule(payload: $payload) { 
    id
    name
  }
}

mutation DeleteDataFlowSchedule($payload: [DataFlowScheduleDeletePayloadInput!]!) {
  mutation: deleteDataFlowSchedule(payload: $payload) { 
    id
    name
  }
}

mutation CreateDataFlowSchedule($payload: [DataFlowScheduleCreatePayloadInput!]!) {
  mutation: createDataFlowSchedule(payload: $payload) { 
    id
    name
  }
}

dataTransform.transform:
(      
   $filterOrReturn := function($data,$dataPath,$filterValue) {
     $isNilOrEmpty($filterValue) ? 
       [$data]
     :
     $filter([$data],function($v){
        $contains($lowercase($path($v,$dataPath)), $lowercase($filterValue))
     })
   };

   $tryCronObject := function($cronString,$timezone) {
     (
        $createCronObject := $tryCatch(
          $cronConverter,
          function($err, $req) {
            $err.message
          }
        );
       $cronObject := $createCronObject($cronString,$timezone);
       $isString($cronObject) ? 
        {        
          "nextExecution": null,
          "validConfiguration": false
        }
        :
        {        
          "nextExecution":$cronObject.schedule().next(),
          "validConfiguration": true
        }
     )
   };

   {
     "total": $.total,
     "edges": [
       $.edges.node~>| $ | (
           $cronData := $tryCronObject($.config.cronString,$.config.timezone);
           {
             "nextExecution": $cronData.nextExecution,
             "validConfiguration": $cronData.validConfiguration
           }
       )|
     ]
   };
)

